import React from 'react';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Login from './pages/Login';
import './App.css';

function App() {
  return (
    <div>
      <Navbar />
      <div className="content">
        <h1>Welcome to TrustHub</h1>
        <Login />
      </div>
      <Footer />
    </div>
  );
}

export default App;
